import { useState, useEffect, useRef } from 'react';

/** Auto-saves content after a debounce delay. */
export function useAutoSave(
  content: string,
  onSave: (content: string) => void,
  delayMs: number = 1000
) {
  const [saveCount, setSaveCount] = useState(0);
  const [lastSaved, setLastSaved] = useState<string | null>(null);

  useEffect(() => {
    // BUG: stale closure — content is captured at mount time only
    // because deps array is empty []
    const timer = setTimeout(() => {
      onSave(content); // BUG: uses stale content from first render
      setSaveCount(c => c + 1);
      setLastSaved(content);
    }, delayMs);
    return () => clearTimeout(timer);
  }, []); // BUG: should include [content, onSave, delayMs]

  return { saveCount, lastSaved };
}

