import { renderHook, act } from '@testing-library/react';
import { useAutoSave } from './useAutoSave';
import { useLatestRef } from './useLatestRef';

beforeEach(() => {
  jest.useFakeTimers();
});

afterEach(() => {
  jest.useRealTimers();
});

test('useAutoSave saves with latest content', async () => {
  const onSave = jest.fn();
  const { rerender } = renderHook(
    ({ content }) => useAutoSave(content, onSave, 500),
    { initialProps: { content: 'initial' } }
  );
  // Change content
  rerender({ content: 'updated' });
  act(() => jest.advanceTimersByTime(600));
  // Should save with 'updated', not 'initial'
  expect(onSave).toHaveBeenCalledWith('updated');
});

test('useAutoSave debounces — only saves once for rapid changes', () => {
  const onSave = jest.fn();
  const { rerender } = renderHook(
    ({ content }) => useAutoSave(content, onSave, 500),
    { initialProps: { content: 'a' } }
  );
  rerender({ content: 'ab' });
  rerender({ content: 'abc' });
  act(() => jest.advanceTimersByTime(600));
  expect(onSave).toHaveBeenCalledTimes(1);
  expect(onSave).toHaveBeenCalledWith('abc');
});

test('useLatestRef always returns latest value', () => {
  const { result, rerender } = renderHook(
    ({ value }) => useLatestRef(value),
    { initialProps: { value: 1 } }
  );
  expect(result.current.current).toBe(1);
  rerender({ value: 99 });
  expect(result.current.current).toBe(99);
});
